using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Threading.Tasks;
namespace TVLounge {
public sealed class ControllerActionBinding {public bool Enabled;public int Mask;public string Action;}
public sealed class GameProfile {
 public bool Enabled=false;public string Name,Executable,Hdr="Keep";public uint Width,Height,Frequency;
 public override string ToString(){return Name+(Enabled?"":" (off)");}
}
internal static class OptionalPolicy {
 public static List<ControllerActionBinding> Defaults(){return new List<ControllerActionBinding>{new ControllerActionBinding{Mask=0x1020,Action="Mute"},new ControllerActionBinding{Mask=0x2020,Action="Desktop"},new ControllerActionBinding{Mask=0x4020,Action="Sleep"}};}
 public static void Validate(Settings settings){var masks=new List<int>();if(settings.ControllerShortcut)masks.Add(settings.ControllerMask);if(settings.QuickMenu)masks.Add(settings.MenuMask);foreach(var action in settings.ControllerActions??new List<ControllerActionBinding>()){if(!new[]{"Mute","VolumeUp","VolumeDown","Desktop","Sleep"}.Contains(action.Action)||!new[]{0x1020,0x2020,0x4020,0x8020}.Contains(action.Mask))throw new InvalidOperationException("Choose a valid controller action and button combination.");if(action.Enabled){if(action.Action=="Sleep"&&!settings.AllowSleep)throw new InvalidOperationException("Enable Sleep in the quick menu before enabling a Sleep shortcut.");masks.Add(action.Mask);}}if(settings.PerformanceEnabled&&settings.PerformanceShortcut)masks.Add(settings.PerformanceMask);if(settings.ReturnGameEnabled&&settings.ReturnGameShortcut)masks.Add(settings.ReturnGameMask);for(int i=0;i<masks.Count;i++)for(int j=0;j<i;j++)if((masks[i]&masks[j])==masks[i]||(masks[i]&masks[j])==masks[j])throw new InvalidOperationException("Two enabled controller shortcuts overlap. Choose different buttons or switch one off.");}
 public static bool AutoReturnEligible(bool enabled,bool active,bool sawLauncher,bool launcherOpen,bool blocked,bool gameRunning,DateTime? closed,DateTime now){return enabled&&active&&sawLauncher&&!launcherOpen&&!blocked&&!gameRunning&&closed.HasValue&&(now-closed.Value).TotalSeconds>=8;}
 public static void ValidateGame(GameProfile profile){if(string.IsNullOrWhiteSpace(profile.Name)||profile.Name.Length>64||!File.Exists(profile.Executable)||!string.Equals(Path.GetExtension(profile.Executable),".exe",StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Enter a name and select the game's actual .exe file.");if(!new[]{"Keep","On","Off"}.Contains(profile.Hdr))throw new InvalidOperationException("Choose a valid HDR preference.");if(profile.Enabled&&profile.Hdr=="Keep"&&profile.Width==0)throw new InvalidOperationException("Choose HDR or a display mode for an enabled game profile.");if((profile.Width==0||profile.Height==0||profile.Frequency==0)&&!(profile.Width==0&&profile.Height==0&&profile.Frequency==0))throw new InvalidOperationException("Choose a complete resolution and refresh rate, or Keep current.");}
}
public sealed class GameSessionRecovery {public string Executable;public VideoPending Before;}
internal static class GameProfiles {
 public static List<GameProfile> Load(){return File.Exists(Storage.PathOf("game-profiles.json"))?Storage.Read<List<GameProfile>>("game-profiles.json"):new List<GameProfile>();}
 public static bool Matches(GameProfile profile,string executable){try{return profile.Enabled&&string.Equals(Path.GetFullPath(profile.Executable),Path.GetFullPath(executable),StringComparison.OrdinalIgnoreCase);}catch{return false;}}
 public static List<GameProfile> Running(List<GameProfile> profiles){var result=new List<GameProfile>();foreach(var profile in profiles.Where(p=>p.Enabled)){var processes=Process.GetProcessesByName(Path.GetFileNameWithoutExtension(profile.Executable));try{if(processes.Any(p=>{try{return Matches(profile,p.MainModule.FileName);}catch{return false;}}))result.Add(profile);}finally{foreach(var p in processes)p.Dispose();}}return result;}
 public static bool Active {get{return File.Exists(Storage.PathOf("game-session.json"));}}
 public static GameSessionRecovery State {get{return Storage.Read<GameSessionRecovery>("game-session.json");}}
 public static async Task<VideoTrial> Begin(string monitor,GameProfile profile){return await Task.Run(()=>{OptionalPolicy.ValidateGame(profile);if(Active)throw new InvalidOperationException("Restore the previous game profile first.");var target=VideoNative.Target(monitor);var before=new VideoPending{Target=target,Mode=VideoNative.Current(monitor),IsHdr=false,AlsoHdr=profile.Hdr!="Keep",Hdr=VideoNative.Hdr(target).Enabled};if(profile.Hdr!="Keep")VideoSession.RememberHdr(target);Storage.Save("game-session.json",new GameSessionRecovery{Executable=profile.Executable,Before=before});return new VideoTrial(before,()=>{if(profile.Hdr!="Keep"&&VideoNative.Hdr(target).Enabled!=(profile.Hdr=="On"))VideoNative.Hdr(target,profile.Hdr=="On");if(profile.Width!=0){var mode=VideoNative.Modes(monitor).FirstOrDefault(m=>m.Width==profile.Width&&m.Height==profile.Height&&m.Frequency==profile.Frequency);if(mode.Width==0)throw new InvalidOperationException("The saved game resolution is unavailable on this TV.");VideoNative.Apply(target,mode);}},VideoSession.Rollback,20000);});}
 public static void Restore(){if(!Active)return;VideoSession.RecoverPending();VideoSession.Rollback(State.Before);File.Delete(Storage.PathOf("game-session.json"));}
 public static void ClearRejected(){if(!File.Exists(Storage.PathOf("pending-video.json")))File.Delete(Storage.PathOf("game-session.json"));}
}
internal static class CouchPower {
 [StructLayout(LayoutKind.Sequential)]struct Luid {public uint Low;public int High;}
 [StructLayout(LayoutKind.Sequential)]struct Privileges {public uint Count;public Luid Id;public uint Attributes;}
 [DllImport("advapi32.dll",SetLastError=true)]static extern bool OpenProcessToken(IntPtr process,uint access,out IntPtr token);
 [DllImport("advapi32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern bool LookupPrivilegeValue(string system,string name,out Luid value);
 [DllImport("advapi32.dll",SetLastError=true)]static extern bool AdjustTokenPrivileges(IntPtr token,bool disable,ref Privileges state,uint size,out Privileges previous,out uint returned);
 [DllImport("kernel32.dll")]static extern bool CloseHandle(IntPtr handle);
 [DllImport("powrprof.dll",SetLastError=true)] [return:MarshalAs(UnmanagedType.U1)]static extern bool SetSuspendState([MarshalAs(UnmanagedType.U1)]bool hibernate,[MarshalAs(UnmanagedType.U1)]bool force,[MarshalAs(UnmanagedType.U1)]bool disableWake);
 public static void Sleep(){IntPtr token;using(var process=Process.GetCurrentProcess())if(!OpenProcessToken(process.Handle,0x28,out token))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());try{Luid id;if(!LookupPrivilegeValue(null,"SeShutdownPrivilege",out id))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error());var requested=new Privileges{Count=1,Id=id,Attributes=2};Privileges previous;uint size;bool adjusted=AdjustTokenPrivileges(token,false,ref requested,16,out previous,out size);int error=Marshal.GetLastWin32Error();if(!adjusted||error!=0)throw new System.ComponentModel.Win32Exception(error,"Windows did not grant permission to sleep.");try{if(!SetSuspendState(false,false,false))throw new System.ComponentModel.Win32Exception(Marshal.GetLastWin32Error(),"Windows could not put the PC to sleep.");}finally{Privileges unused;AdjustTokenPrivileges(token,false,ref previous,16,out unused,out size);}}finally{CloseHandle(token);}}
}internal static class OptionalTests {
 public static void Run(){Action<bool,string> check=(ok,label)=>{if(!ok)throw new Exception(label);};var settings=new Settings();check(!settings.AutoReturn&&!settings.AllowSleep&&!settings.GameProfilesEnabled&&!settings.ControllerActions.Any(a=>a.Enabled),"New features must be opt-in");OptionalPolicy.Validate(settings);settings.ControllerActions[0].Enabled=true;settings.ControllerActions[0].Mask=settings.MenuMask;bool failed=false;try{OptionalPolicy.Validate(settings);}catch{failed=true;}check(failed,"Duplicate enabled shortcut rejected");settings.ControllerActions[0].Enabled=false;settings.ControllerActions[2].Enabled=true;failed=false;try{OptionalPolicy.Validate(settings);}catch{failed=true;}check(failed,"Disabled Sleep feature cannot have active sleep binding");var now=DateTime.UtcNow;check(OptionalPolicy.AutoReturnEligible(true,true,true,false,false,false,now.AddSeconds(-9),now),"Launcher exit restores after grace period");check(!OptionalPolicy.AutoReturnEligible(false,true,true,false,false,false,now.AddSeconds(-9),now),"Off disables auto return");check(!OptionalPolicy.AutoReturnEligible(true,true,true,false,false,true,now.AddSeconds(-9),now),"Running game blocks auto return");check(!OptionalPolicy.AutoReturnEligible(true,true,false,false,false,false,now.AddSeconds(-9),now),"Never observed launcher cannot trigger");check(!OptionalPolicy.AutoReturnEligible(true,true,true,false,false,false,now.AddSeconds(-2),now),"Transient launcher loss cannot trigger");var profile=new GameProfile{Enabled=true,Executable=@"C:\Games\Game.exe"};check(GameProfiles.Matches(profile,@"c:\games\game.exe")&&!GameProfiles.Matches(profile,@"C:\Elsewhere\Game.exe"),"Profiles match full executable path");profile.Enabled=false;check(!GameProfiles.Matches(profile,@"C:\Games\Game.exe"),"Disabled profiles never match");using(var self=Process.GetCurrentProcess()){var currentProfile=new GameProfile{Enabled=true,Executable=self.MainModule.FileName};check(GameProfiles.Running(new List<GameProfile>{currentProfile}).Count==1,"Live exact-path game detection failed");currentProfile.Enabled=false;check(GameProfiles.Running(new List<GameProfile>{currentProfile}).Count==0,"Disabled game should not be polled as active");string shell=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Windows),@"System32\WindowsPowerShell\v1.0\powershell.exe");using(var child=Process.Start(new ProcessStartInfo(shell,"-NoProfile -NonInteractive -Command Start-Sleep -Milliseconds 500"){UseShellExecute=false,CreateNoWindow=true})){check(GameActivity.Any(new HashSet<uint>{(uint)self.Id}),"Live child-process game guard failed");child.WaitForExit(5000);}}string oldData=Storage.Data;try{Storage.Data=Path.Combine(oldData,"optional-launcher-test");var fake=new FakeDevices();var engine=new Engine(fake);engine.Activate(new Settings{MonitorId="tv",Launcher="Playnite",TimeoutSeconds=3});check(fake.PlayniteOpen&&Storage.Read<Snapshot>("restore.json").Launcher=="Playnite","Playnite enters after devices and persists launcher");engine.Restore(3);check(!fake.PlayniteOpen&&!engine.Active,"Playnite restores desktop");}finally{Storage.Data=oldData;}File.WriteAllText(Storage.PathOf("optional-test.txt"),"PASS: opt-in defaults, controller conflicts, sleep dependency, launcher-exit grace and active-game suppression, exact game-path matching and disabled profiles, Playnite session ordering and restoration. PC sleep was not invoked.");}
}
}
